import { Refine, Authenticated } from '@refinedev/core';
import { RefineThemedLayoutV2, ErrorComponent } from '@refinedev/antd';
import { dataProvider } from './providers/dataProvider';
import { authProvider } from './providers/authProvider';
import { accessControlProvider } from './providers/accessControlProvider';
import { i18nProvider } from './providers/i18n';
import { resources } from './config/resources';
import { App as AntdApp, ConfigProvider } from 'antd';
import { antdTheme } from './config/theme';

export default function App() {
  return (
    <ConfigProvider theme={antdTheme}>
      <AntdApp>
        <Refine
          dataProvider={dataProvider}
          authProvider={authProvider}
          accessControlProvider={accessControlProvider}
          i18nProvider={i18nProvider}
          resources={resources}
          options={{ syncWithLocation: true, warnWhenUnsavedChanges: true }}
        >
          <Authenticated key="app">
            <RefineThemedLayoutV2 Sider={LayerSider} Header={LayerHeader}>
              <Routes />
            </RefineThemedLayoutV2>
          </Authenticated>
        </Refine>
      </AntdApp>
    </ConfigProvider>
  );
}

async getList({ resource, pagination, sorters, filters, meta }) {
  const params = buildQuery({ pagination, sorters, filters, meta }); // 见 API 契约章
  const res = await http.get(`/api/${resource}`, { params });
  return { data: res.data.items, total: res.data.total };
}

export const authProvider: AuthProvider = {
  login: async ({ username, password }) => {
    const { data } = await http.post('/api/auth/login', { username, password });
    localStorage.setItem('token', data.accessToken);
    localStorage.setItem('me', JSON.stringify(data.user)); // role / scope / layer
    return { success: true, redirectTo: '/' };
  },
  logout: async () => { localStorage.clear(); return { success: true }; },
  check: async () => {
    const token = localStorage.getItem('token');
    return token ? { authenticated: true } : { authenticated: false, redirectTo: '/login' };
  },
  getIdentity: async () => JSON.parse(localStorage.getItem('me') || 'null'),
  getPermissions: async () => {
    const me = JSON.parse(localStorage.getItem('me') || '{}');
    return me.role; // 或 me.permissions 权限点数组
  },
};

export const accessControlProvider: AccessControlProvider = {
  can: async ({ resource, action, params }) => {
    const me = getIdentity();
    // 数据作用域维度：resource 是否在该层菜单可见
    if (!inLayer(me.layer, resource)) return { can: false, reason: '当前层级无权访问' };
    // 功能权限维度：权限点检查（如导出需 data:export）
    if (action === 'export' && !me.permissions.includes('data:export')) {
      return { can: false, reason: '缺少导出权限' };
    }
    // 位阶维度：只读账号仅允许 list / show
    if (me.readonly && !['list', 'show'].includes(action)) {
      return { can: false, reason: '当前账号为只读，不可写操作' };
    }
    return { can: true };
  },
};

@Injectable()
export class AbacGuard implements CanActivate {
  async canActivate(ctx: ExecutionContext) {
    const req = ctx.switchToHttp().getRequest();
    const user = req.user;                 // role / scope(regionPath|selfId) / perms[]
    const { resource, action } = metaOf(ctx); // 由 @Abac('providers', 'review') 注入
    // 1 位阶：只读账号拒绝写动作
    if (user.readonly && !READONLY_OK.has(action)) return false;
    // 2 功能权限
    if (!user.perms.includes(permKey(resource, action))) return false;
    // 3 数据作用域：注入 where（regionPath 前缀 / selfId）
    req.scopeWhere = buildScopeWhere(user);
    return true;
  }
}

enum RoleType { USER SERVICE_PROVIDER AGENT ADMIN }
model User { id String @id @default(cuid()) username String @unique password String role RoleType name String phone String? regionPath String? // 隔离前缀，如 '乌鲁木齐/天山区' status Status tier MemberTier // USER 的会员等级 balance Int @default(0) points Int @default(0) createdAt DateTime @default(now()) agent Agent? provider ServiceProvider? }
model Region { id String @id @default(cuid()) name String level RegionLevel // PROVINCE / CITY / DISTRICT regionPath String @unique // '乌鲁木齐/天山区' agentId String? agent Agent? @relation(fields: [agentId], references: [id]) }
model Agent { id String @id @default(cuid()) userId String @unique user User @relation(fields: [userId], references: [id]) regionId String region Region @relation(fields: [regionId], references: [id]) status AgentStatus // NORMAL / REVIEW / DISABLED monthlyFlow Int @default(0) }
model ServiceProvider { id String @id @default(cuid()) userId String @unique user User @relation(fields: [userId], references: [id]) type String // 婚庆主持 / 摄影摄像 ... regionPath String status ProviderStatus // PENDING_REVIEW / APPROVED / REJECTED / REVIEWING / UPGRADING qualification Json? // 资质项数组 }
model Service { id String @id @default(cuid()) providerId String name String type String price Int status ServiceStatus // ON_SALE / DRAFT / OFF_SHELF template Boolean @default(false) // 模板审核复用 }
model Order { id String @id @default(cuid()) orderNo String @unique userId String providerId String serviceId String amount Int status OrderStatus // PENDING_ACCEPT / IN_PROGRESS / DONE / AFTER_SALE createdAt DateTime @default(now()) }
model Wallet { id String @id @default(cuid()) ownerType String // AGENT / PROVIDER ownerId String balance Int frozen Int totalFlow Int }
model Ledger { id String @id @default(cuid()) walletId String type LedgerType // IN / PENDING / OUT amount Int balanceAfter Int createdAt DateTime @default(now()) }
model Withdrawal { id String @id @default(cuid()) providerId String amount Int account String status ReviewStatus // PENDING / APPROVED / REJECTED createdAt DateTime @default(now()) }
model Feedback { id String @id @default(cuid()) no String @unique kind String // 服务投诉 / 价格争议 / 服务满意 ... userId String targetId String status FeedbackStatus // NEGOTIATING / HANDLED / UPGRADED / CLOSED content String createdAt DateTime @default(now()) }
model Message { id String @id @default(cuid()) title String kind MessageKind // 订单 / 服务 / 评价 / 权益 / 公告 / 系统通知 scope String // 全平台 / 区域 / 指定用户 status MessageStatus // UNREAD / READ / PENDING_REVIEW / PUBLISHED body String? createdAt DateTime @default(now()) }
model Role { id String @id @default(cuid()) name String layer LayerType // CONSOLE / AGENT / PROVIDER type RoleKind // BUILTIN / CUSTOM scope ScopeType // ALL / REGION / SELF perms String[] // 权限点 key 数组（10 域 28 点） level Int // 位阶：100 超级 / 90 运维 / 80 审核 / 80 财务 / 60 客服 accountCount Int @default(0) }
model UserRole { userId String roleId String @@id([userId, roleId]) }
model Coupon { id String @id @default(cuid()) title String amount Int validFrom DateTime validTo DateTime condition String? status CouponStatus }
model UserCoupon { id String @id @default(cuid()) userId String coupon Coupon @relation(fields: [couponId], references: [id]) couponId String used Boolean @default(false) }

interface ListPageConfig {
  title: string; sub: string; chip: string;
  columns: ColumnDef[];            // 含 n(数值右对齐)、status(状态标签列)、render
  filters: FilterTab[];            // { key, label, value? } 可点击筛选按钮
  searchPlaceholder?: string;      // 关键词搜索 + 清空叉
  exportable?: boolean;            // 受 data:export 控制
  actions: 'view' | 'edit' | 'review' | 'ro' | 'none' | 'cfg';
  creatable?: boolean;             // 「＋新建」
  scope?: string;                  // 作用域 chip
}
export function DataListPage({ config, objectScope }: Props) {
  const { data, tableProps, setCurrent } = useList({ resource, filters, sorters });
  return (
    <AntdList header={renderHeader(config, objectScope)}>
      <Table {...tableProps} rowKey="id" columns={buildColumns(config)} />
    </AntdList>
  );
}

export function DetailDrawer({ resource, id, config, onClose }) {
  const { queryResult } = useShow({ resource, id });      // 详情
  const { mutate } = useUpdate();                          // 编辑保存
  const [mode, setMode] = useState<'view' | 'edit'>('view');
  const [form] = Form.useForm();
  useEffect(() => { if (queryResult.data?.data) form.setFieldsValue(queryResult.data.data); }, [queryResult.data]);
  return (
    <Drawer open title={config.title} width={560} extra={config.actions}>
      {mode === 'view'
        ? <Descriptions column={1} items={buildView(config, queryResult.data?.data)} />
        : <Form form={form} onFinish={save} layout="vertical">{buildForm(config)}</Form>}
    </Drawer>
  );
}

const { mutate: approve } = useCustomMutation();
const approveIt = () => approve({
  url: `/api/${resource}/${id}/approve`,
  method: 'post', values: { comment: form.getFieldValue('comment') },
}, { onSuccess: () => { message.success('已通过'); invalidate(); onClose(); } });

// 驳回：AntD Modal.confirm 内嵌 Form，comment 必填校验，不满足拦截
const rejectIt = () => Modal.confirm({
  title: '驳回确认', content: <Form form={rejForm}><Form.Item name="comment"
    rules={[{ required: true, message: '请填写驳回原因' }]}>
    <Input.TextArea /></Form.Item></Form>,
  onOk: () => approve({ url: `/api/${resource}/${id}/reject`, method: 'post', values: rejForm.getFieldsValue() }),
});

const PERM_GROUPS = [
  { domain: '用户与账号', key: 'user', perms: [{ label: '用户查询', key: 'user:view' }, { label: '用户编辑', key: 'user:edit' }] },
  { domain: '入驻与服务商', key: 'provider', perms: [/* provider:review / qualification / upgrade */] },
  // ... 10 域 28 点（见角色与权限章）
];

function PermCheckGroup({ layer, value, onChange }) {
  const groups = PERM_GROUPS.filter(g => layerDomains[layer].includes(g.key)); // 按层过滤
  return (
    <div className="perm-groups">
      {groups.map(g => (
        <Card key={g.key} size="small" title={g.domain}>
          <Checkbox.Group options={g.perms} value={value} onChange={onChange} />
        </Card>
      ))}
    </div>
  );
}

import type { ThemeConfig } from 'antd';
